$ErrorActionPreference='Stop'
Add-Type -TypeDefinition @"
using System;using System.Runtime.InteropServices;using Microsoft.Win32.SafeHandles;
public static class FixtureIdentityProbe {
 [StructLayout(LayoutKind.Sequential)] public struct IdInfo {public ulong Volume;public ulong Low;public ulong High;}
 [StructLayout(LayoutKind.Sequential)] public struct StandardInfo {public long Allocation;public long End;public uint Links;[MarshalAs(UnmanagedType.U1)] public bool DeletePending;[MarshalAs(UnmanagedType.U1)] public bool Directory;}
 [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)] public static extern SafeFileHandle CreateFileW(string path,uint access,uint share,IntPtr security,uint disposition,uint flags,IntPtr template);
 [DllImport("kernel32.dll",SetLastError=true,EntryPoint="GetFileInformationByHandleEx")] public static extern bool Id(SafeFileHandle handle,int cls,out IdInfo info,uint size);
 [DllImport("kernel32.dll",SetLastError=true,EntryPoint="GetFileInformationByHandleEx")] public static extern bool Standard(SafeFileHandle handle,int cls,out StandardInfo info,uint size);
 public static SafeFileHandle Open(string path){var h=CreateFileW(path,0,7,IntPtr.Zero,3,0x02200000,IntPtr.Zero);if(h.IsInvalid)throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error());return h;}
 public static IdInfo Identity(SafeFileHandle h){IdInfo i;if(!Id(h,18,out i,(uint)Marshal.SizeOf(typeof(IdInfo))))throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error());return i;}
 public static StandardInfo State(SafeFileHandle h){StandardInfo i;if(!Standard(h,1,out i,(uint)Marshal.SizeOf(typeof(StandardInfo))))throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error());return i;}
 public static bool Same(IdInfo a,IdInfo b){return a.Volume==b.Volume&&a.Low==b.Low&&a.High==b.High;}
}
"@
$base=[IO.Path]::GetFullPath($PSScriptRoot);$name='identity-probe-'+[Guid]::NewGuid().ToString('N');$root=[IO.Path]::Combine($base,$name);if([IO.Path]::GetDirectoryName($root) -cne $base){throw 'probe containment failed'};[IO.Directory]::CreateDirectory($root)|Out-Null
$names=@('normal','original','renamed','replacement','pending','link','target','survivor');$handles=New-Object 'System.Collections.Generic.List[object]'
try{
 $normal=Join-Path $root 'normal';[IO.Directory]::CreateDirectory($normal)|Out-Null;$h=[FixtureIdentityProbe]::Open($normal);$handles.Add($h);$id=[FixtureIdentityProbe]::Identity($h);if(-not [FixtureIdentityProbe]::State($h).Directory){throw 'not a directory'};[IO.Directory]::Delete($normal,$false);$pending=[FixtureIdentityProbe]::State($h).DeletePending;if(-not $pending){throw 'delete pending not observed'};$h.Dispose();if([IO.Directory]::Exists($normal)){throw 'normal cleanup path survives'};Write-Output 'PASS original directory, pending state and closure'
 $original=Join-Path $root 'original';$renamed=Join-Path $root 'renamed';[IO.Directory]::CreateDirectory($original)|Out-Null;$h=[FixtureIdentityProbe]::Open($original);$handles.Add($h);$before=[FixtureIdentityProbe]::Identity($h);[IO.Directory]::Move($original,$renamed);if([IO.Directory]::Exists($original)){throw 'rename did not remove old pathname'};$moved=[FixtureIdentityProbe]::Open($renamed);$handles.Add($moved);if(-not [FixtureIdentityProbe]::Same($before,[FixtureIdentityProbe]::Identity($moved))){throw 'renamed identity mismatch'};[IO.Directory]::CreateDirectory($original)|Out-Null;$replacement=[FixtureIdentityProbe]::Open($original);$handles.Add($replacement);$other=[FixtureIdentityProbe]::Identity($replacement);if([FixtureIdentityProbe]::Same($before,$other)){throw 'replacement identity not rejected'};$wrong=$before;$wrong.Low=$wrong.Low -bxor [uint64]1;if([FixtureIdentityProbe]::Same($before,$wrong)){throw 'wrong file id accepted'};$wrong=$before;$wrong.Volume=$wrong.Volume -bxor [uint64]1;if([FixtureIdentityProbe]::Same($before,$wrong)){throw 'wrong volume id accepted'};Write-Output 'PASS rename, replacement, wrong file and volume identity'
 $survivor=Join-Path $root 'survivor';[IO.Directory]::CreateDirectory($survivor)|Out-Null;$owned=Join-Path $survivor 'owned.bin';[IO.File]::WriteAllText($owned,'synthetic');$failedDelete=$false;try{[IO.Directory]::Delete($survivor,$false)}catch{$failedDelete=$true};if(-not $failedDelete -or -not [IO.Directory]::Exists($survivor)){throw 'nonempty directory survival not observed'};[IO.File]::Delete($owned);[IO.Directory]::Delete($survivor,$false);Write-Output 'PASS nonempty directory survives nonrecursive deletion'
 $target=Join-Path $root 'target';$link=Join-Path $root 'link';[IO.Directory]::CreateDirectory($target)|Out-Null;try{$null=New-Item -ItemType Junction -Path $link -Target $target -ErrorAction Stop;$attr=(Get-Item -LiteralPath $link -Force).Attributes;if(($attr -band [IO.FileAttributes]::ReparsePoint) -eq 0){throw 'reparse flag absent'};$jh=[FixtureIdentityProbe]::Open($link);$handles.Add($jh);$jId=[FixtureIdentityProbe]::Identity($jh);$th=[FixtureIdentityProbe]::Open($target);$handles.Add($th);if([FixtureIdentityProbe]::Same($jId,[FixtureIdentityProbe]::Identity($th))){throw 'reparse substitution not distinguished'};Write-Output 'PASS junction substitution identified'}catch{if(-not [IO.Directory]::Exists($link)){Write-Output 'UNVERIFIED junction creation unavailable'}else{throw}}
 $closed=[FixtureIdentityProbe]::Open($target);$closed.Dispose();$failed=$false;try{$null=[FixtureIdentityProbe]::Identity($closed)}catch{$failed=$true};if(-not $failed){throw 'closed identity query accepted'};Write-Output 'PASS failed identity query rejected'
}finally{
 foreach($h in $handles){if($h -and -not $h.IsClosed){$h.Dispose()}}
 $owned=Join-Path (Join-Path $root 'survivor') 'owned.bin';if([IO.File]::Exists($owned)){[IO.File]::Delete($owned)}
 foreach($n in $names){$p=Join-Path $root $n;if([IO.Directory]::Exists($p)){[IO.Directory]::Delete($p,$false)}}
 if([IO.Directory]::Exists($root)){[IO.Directory]::Delete($root,$false)}
}
